local Translate = ns.Lore.Translate

Translate("ptBR", "azeroth", {
	title = "Azeroth",
	sections = {
		{
			title = "Resumo",
			text = [=[Azeroth é o mundo. Seus mares abrigam os continentes dos {link:eastern-kingdoms}Reinos do Leste{/link}, de {link:kalimdor}Kalimdor{/link} e da gélida Nortúndria, além de incontáveis ilhas. Selvas, desertos, florestas e campos de gelo ficam lado a lado por toda a sua extensão, e em cada terra as ruínas de eras mais antigas repousam sob as cidades das novas. É um mundo de muitos povos e de memória muito longa. Vez após vez, foi feito sangrar por poderes que o cobiçam, e vez após vez resistiu.]=],
		},
		{
			title = "Origens",
			text = [=[As histórias mais antigas dizem que Azeroth foi moldado pelos Titãs, seres divinos que viajavam entre as estrelas para trazer ordem aos mundos que encontravam. Quando chegaram a Azeroth, ele era dominado por elementais furiosos e por males antigos que haviam se agarrado ao mundo. As crônicas chamam esses males de Deuses Antigos. Os Titãs quebraram o poder de ambos. Prenderam os senhores elementais num reino separado do mundo e aprisionaram os Deuses Antigos nas profundezas da terra, pois não podiam matá-los sem ferir o próprio mundo. Então os Titãs moldaram a terra. Seus servos ergueram as montanhas, escavaram os vales e encheram os mares. Os terranos, seres de pedra viva, foram postos para cuidar dos lugares profundos do mundo. Entre os dragões, os Titãs escolheram cinco e deram a cada um uma parte de seu poder. Estes se tornaram os Aspectos, encarregados de guardar Azeroth quando seus criadores tivessem partido. Então os Titãs partiram, e o mundo foi deixado aos seus próprios povos.]=],
		},
		{
			title = "As Eras do Mundo",
			text = [=[• {b}O Império Kaldorei.{/b} No coração de um único grande continente ficava o {link:well-of-eternity}Poço da Eternidade{/link}. Em suas margens, os {link:night-elves}elfos noturnos{/link} ergueram um império de maravilhas sob a {link:queen-azshara}Rainha Azshara{/link}.
• {b}A Guerra dos Antigos.{/b} A magia imprudente dos Bem-nascidos atraiu o olhar da {link:burning-legion}Legião Ardente{/link}. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, os elfos noturnos lutaram pela sobrevivência do mundo, e a destruição do Poço provocou a {link:great-sundering}Grande Cisão{/link}. O continente único partiu-se em muitos.
• {b}As Raças Jovens.{/b} Nas eras que se seguiram, os impérios trolls declinaram e os {link:dwarves}anões{/link} despertaram sob as montanhas. Os {link:high-elves}altos elfos{/link} fundaram {link:quel-thalas}Quel'Thalas{/link}, e as tribos {link:humans}humanas{/link} uniram-se como {link:arathor}Arathor{/link} para lutar nas {link:troll-wars}Guerras Trolls{/link}.
• {b}A Era da {link:horde}Horda{/link}.{/b} Quando o {link:dark-portal}Portal Negro{/link} se abriu, os {link:orcs}orcs{/link} de outro mundo invadiram Azeroth. Seguiram-se a {link:first-war}Primeira Guerra{/link}, a {link:second-war}Segunda Guerra{/link} e a {link:third-war}Terceira Guerra{/link}, cada uma mais terrível que a anterior.]=],
		},
		{
			title = "Um Nome Compartilhado",
			text = [=[O nome Azeroth também pertenceu um dia a um reino humano. Os exilados arathi que se estabeleceram nas florestas do sul chamaram seu novo reino de Azeroth, e sua capital era {link:stormwind-city}Ventobravo{/link}. Com o tempo, o reino passou a ser conhecido pelo nome de sua cidade, e hoje é o {link:kingdom-of-stormwind}Reino de Ventobravo{/link}. Velhos soldados da {link:first-war}Primeira Guerra{/link} ainda às vezes falam de "Azeroth" querendo dizer apenas o reino que perderam.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[A {link:third-war}Terceira Guerra{/link} terminou com a queda de {link:archimonde}Archimonde{/link} ao pé de {link:nordrassil}Nordrassil{/link}, mas não trouxe paz. O {link:scourge}Flagelo{/link} domina o norte de {link:lordaeron}Lordaeron{/link}. Servos da {link:burning-legion}Legião Ardente{/link} ainda assombram as florestas de {link:kalimdor}Kalimdor{/link}. A {link:alliance}Aliança{/link} e a {link:horde}Horda{/link}, que lutaram juntas no {link:mount-hyjal}Monte Hyjal{/link}, agora se vigiam com desconfiança através dos {link:the-barrens}Sertões{/link} e dos bosques de {link:ashenvale}Vale Gris{/link}. Sob a {link:blackrock-mountain}Montanha Rocha Negra{/link}, os {link:dark-iron-dwarves}Anões Ferro Negro{/link} servem a um senhor de fogo vivo. Azeroth sobreviveu a todas as guerras travadas sobre ele até hoje. Nenhum cronista ousaria dizer que ele não pode cair.]=],
		},
	},
})

Translate("ptBR", "eastern-kingdoms", {
	title = "Reinos do Leste",
	sections = {
		{
			title = "Resumo",
			text = [=[Os Reinos do Leste estendem-se dos picos gelados de {link:alterac-mountains}Alterac{/link} às selvas do {link:stranglethorn-vale}Espinhaço{/link}. São a terra natal da {link:humans}humanidade{/link}, dos {link:dwarves}anões{/link} e dos {link:gnomes}gnomos{/link}, e dos {link:high-elves}altos elfos{/link} de {link:quel-thalas}Quel'Thalas{/link}. Aqui se ergueram os grandes reinos humanos de outrora, e aqui a {link:horde}Horda{/link} travou sua primeira guerra contra {link:azeroth}Azeroth{/link}. As terras carregam as cicatrizes de todas as guerras desde então. Reinos outrora orgulhosos jazem em ruínas, e o norte tornou-se uma terra dos mortos.]=],
		},
		{
			title = "Origens",
			text = [=[Antes da {link:great-sundering}Grande Cisão{/link}, estas terras eram os confins orientais de um único continente. Quando o {link:well-of-eternity}Poço da Eternidade{/link} foi destruído, os mares avançaram e as arrancaram. O que restou já era uma terra antiga. Os Titãs haviam deixado suas obras aqui, entre elas a câmara de {link:uldaman}Uldaman{/link}, nos pedregosos {link:badlands}Ermos{/link}. Seus servos terranos dormiam em seus salões. Ao longo de longas eras, os terranos mudaram. Sua carne amoleceu e suas vidas encurtaram, e deles vieram os anões de Khaz Modan. Outro povo forjado pelos Titãs, dizem os escritos, deu origem aos gnomos. Os trolls eram ainda mais antigos nestas terras. Os Amani governavam as florestas do norte, e os Gurubashi dominavam as selvas do sul.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Chegada dos Elfos.{/b} Exilados de {link:kalimdor}Kalimdor{/link}, os Bem-nascidos cruzaram o mar e fundaram {link:quel-thalas}Quel'Thalas{/link} nas florestas do norte, em terras que os Amani reivindicavam como suas.
• {b}Arathor.{/b} As tribos humanas do norte foram unidas por {link:thoradin}Thoradin{/link}, que ergueu a cidade de {link:stromgarde-keep}Strom{/link}. Junto com os elfos, seus exércitos derrotaram os Amani nas {link:troll-wars}Guerras Trolls{/link}. Em troca, os elfos ensinaram aos humanos os caminhos da magia de {link:arathor}Arathor{/link}, e Dalaran foi mais tarde fundada pelos magos dessa linhagem.
• {b}Os Sete Reinos.{/b} Com o tempo, Arathor se dividiu. Os reinos de {link:lordaeron}Lordaeron{/link}, {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiraz{/link}, {link:alterac-mountains}Alterac{/link}, {link:dalaran}Dalaran{/link} e Stromgarde surgiram no norte. No sul, exilados arathi fundaram o reino que se tornou o {link:kingdom-of-stormwind}Reino de Ventobravo{/link}.
• {b}Os Três Martelos.{/b} Sob as montanhas, os anões de {link:kingdom-of-ironforge}Altaforja{/link} dividiram-se nos clãs Barbabronze, Martelo Feroz e {link:dark-iron-dwarves}Ferro Negro{/link}. Sua guerra terminou em fogo. O feiticeiro-thane Ferro Negro {link:ruins-of-thaurissan}Thaurissan{/link} invocou Ragnaros, senhor do fogo, e a invocação ergueu a {link:blackrock-mountain}Montanha Rocha Negra{/link} e queimou as terras ao redor.
• {b}As Guerras da {link:horde}Horda{/link}.{/b} O {link:dark-portal}Portal Negro{/link} abriu-se no sul. {link:stormwind-city}Ventobravo{/link} caiu na {link:first-war}Primeira Guerra{/link}. A {link:alliance}Aliança{/link} de Lordaeron repeliu a Horda na {link:second-war}Segunda Guerra{/link}. Depois vieram a praga da morte-vida, o {link:culling-of-stratholme}Expurgo de Stratholme{/link} e a {link:fall-of-lordaeron}Queda de Lordaeron{/link}.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[{link:stormwind-city}Ventobravo{/link} reergueu-se, embora seu rei esteja desaparecido e seu regente, {link:bolvar-fordragon}Bolvar Fordragon{/link}, governe um reino sobrecarregado. {link:magni-bronzebeard}Magni Bronzebeard{/link} reina em {link:ironforge}Altaforja{/link}, que também abriga os gnomos, pois {link:gnomeregan}Gnomeregan{/link} se perdeu para sua própria ruína. Ao norte da {link:thandol-span}Ponte Thandol{/link}, o grande reino de {link:lordaeron}Lordaeron{/link} não existe mais. O {link:scourge}Flagelo{/link} domina as Terras Pestilentas. Os fanáticos da {link:scarlet-crusade}Cruzada Escarlate{/link} o combatem com fogo e suspeita em igual medida. Nas ruínas da antiga capital, os {link:forsaken}Renegados{/link} fizeram um lar sob a terra. Na {link:blackrock-mountain}Montanha Rocha Negra{/link}, {link:dark-iron-dwarves}Ferro Negro{/link} e orcs guerreiam entre si. E no sul, o {link:dark-portal}Portal Negro{/link} está silencioso na {link:blasted-lands}Barreira do Inferno{/link}.]=],
		},
	},
})

Translate("ptBR", "kalimdor", {
	title = "Kalimdor",
	sections = {
		{
			title = "Resumo",
			text = [=[Kalimdor fica do outro lado do mar, a oeste dos {link:eastern-kingdoms}Reinos do Leste{/link}. É uma terra de florestas antigas e cânions vermelhos, de grandes planícies e desertos ardentes. É a terra natal dos {link:night-elves}elfos noturnos{/link} e dos {link:tauren}taurens{/link}, e o antigo coração do mundo. A Kalimdor de hoje é apenas o que sobreviveu à {link:great-sundering}Grande Cisão{/link}. Antes desse cataclismo, um único continente reunia quase todas as terras de {link:azeroth}Azeroth{/link}, e o lago em seu centro era o {link:well-of-eternity}Poço da Eternidade{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Os povos mais antigos de Kalimdor eram os trolls, cujos impérios se espalharam por todo o continente primordial. Uma tribo de trolls que se estabeleceu junto ao Poço foi transformada por seu poder ao longo de muitas gerações. Tornaram-se os elfos noturnos, que chamaram a terra de Kalimdor. Junto ao Poço, construíram as cidades do Império Kaldorei sob a {link:queen-azshara}Rainha Azshara{/link}. Sua busca pela {link:arcane-magic}magia arcana{/link} atraiu a {link:burning-legion}Legião Ardente{/link} ao mundo. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, o Poço foi destruído, e o continente se despedaçou. Os mares invadiram a ferida, e o Voragem agita-se ali desde então. Nas encostas do {link:mount-hyjal}Monte Hyjal{/link}, os sobreviventes plantaram {link:nordrassil}Nordrassil{/link}, e por dez mil anos os elfos noturnos mantiveram uma vigília oculta sobre suas florestas.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Longa Vigília.{/b} Sob {link:malfurion-stormrage}Malfurion Stormrage{/link} e {link:tyrande-whisperwind}Tyrande Whisperwind{/link}, os elfos noturnos renunciaram à magia arcana. Os druidas dormiam no {link:emerald-dream}Sonho Esmeralda{/link}, e as {link:sentinels}Sentinelas{/link} guardavam as florestas sozinhas.
• {b}Os Povos das Terras Selvagens.{/b} Pelas planícies vagavam os taurens. Durante gerações foram assediados pelos {link:centaurs}centauros{/link} do sul, pelos {link:quilboar}javatuscos{/link} dos {link:the-barrens}Sertões{/link}, pelas {link:harpies}harpias{/link} dos penhascos e pelos {link:furbolgs}pelursos{/link} das florestas.
• {b}A Terceira Guerra.{/b} Na {link:third-war}Terceira Guerra{/link}, uma nova {link:horde}Horda{/link} sob {link:thrall}Thrall{/link} cruzou o mar, assim como os humanos de {link:jaina-proudmoore}Jaina Proudmoore{/link}. A {link:burning-legion}Legião Ardente{/link} os seguiu. {link:orcs}Orcs{/link}, humanos e elfos noturnos, antes estranhos e inimigos, lutaram juntos na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, e ali {link:archimonde}Archimonde{/link} foi destruído.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[Kalimdor não é mais uma terra oculta. Os elfos noturnos plantaram uma nova árvore, {link:teldrassil}Teldrassil{/link}, e sua cidade, {link:darnassus}Darnassus{/link}, contempla o mar do norte. Os orcs fundaram {link:durotar}Durotar{/link} e a cidade de {link:orgrimmar}Orgrimmar{/link}, e os taurens de {link:cairne-bloodhoof}Cairne Bloodhoof{/link} fizeram do {link:thunder-bluff}Penhasco do Trovão{/link} seu lar em {link:mulgore}Mulgore{/link}. Os {link:darkspear-trolls}trolls Lançanegra{/link} vivem ao lado dos orcs. {link:jaina-proudmoore}Jaina Proudmoore{/link} governa {link:theramore-isle}Theramore{/link}, no {link:dustwallow-marsh}Pântano Vadeoso{/link}. Ainda assim, a paz de Hyjal está se desfazendo. Lenhadores orcs cortam as árvores de {link:ashenvale}Vale Gris{/link}, e as {link:sentinels}Sentinelas{/link} respondem com flechas. Goblins do {link:steamwheedle-cartel}Cartel Bondebico{/link} e da {link:venture-company}Empreendimentos S.A.{/link} negociam e saqueiam ao longo das costas. As florestas da {link:felwood}Selva Maleva{/link} ainda carregam a mácula da Legião, e mistérios mais antigos dormem nos desertos do sul.]=],
		},
	},
})

Translate("ptBR", "war-of-the-ancients", {
	title = "Guerra dos Antigos",
	sections = {
		{
			title = "Resumo",
			text = [=[A Guerra dos Antigos foi a primeira invasão de {link:azeroth}Azeroth{/link} pela {link:burning-legion}Legião Ardente{/link}. Foi travada cerca de dez mil anos antes da abertura do {link:dark-portal}Portal Negro{/link} e pôs fim ao Império Kaldorei. Sua última hora trouxe a {link:great-sundering}Grande Cisão{/link}, que partiu o mundo.]=],
		},
		{
			title = "Origens",
			text = [=[Os Bem-nascidos da corte dos elfos noturnos sorviam cada vez mais fundo o poder do {link:well-of-eternity}Poço da Eternidade{/link}. Sua magia foi sentida além do mundo por {link:sargeras}Sargeras{/link}, o titã caído que lidera a {link:burning-legion}Legião Ardente{/link}. Ele sussurrou à {link:queen-azshara}Rainha Azshara{/link}, e ela acreditou nele. {link:azshara}Azshara{/link} e seus Bem-nascidos trabalharam para abrir um portal no Poço, para que Sargeras e seus demônios pudessem entrar em {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "História",
			text = [=[Os primeiros demônios atravessaram, liderados por {link:archimonde}Archimonde{/link} e {link:mannoroth}Mannoroth{/link}, e massacraram os elfos noturnos que se puseram em seu caminho. Formou-se uma resistência contra eles e contra a rainha. Ela era liderada por {link:malfurion-stormrage}Malfurion Stormrage{/link}, um jovem aluno do semideus {link:cenarius}Cenarius{/link}, junto com a sacerdotisa {link:tyrande-whisperwind}Tyrande Whisperwind{/link} e o irmão gêmeo de Malfurion, {link:illidan-stormrage}Illidan Stormrage{/link}. Os semideuses das terras selvagens e as revoadas dragônicas juntaram-se à luta. A guerra esteve quase perdida quando o Guardião da Terra dos dragões traiu sua espécie. Ele era o Aspecto que se tornaria {link:deathwing}Asa da Morte{/link}. Por fim, os defensores alcançaram o palácio dos Bem-nascidos e quebraram seus feitiços no momento em que {link:sargeras}Sargeras{/link} tentava atravessar. O portal desmoronou, e o {link:well-of-eternity}Poço da Eternidade{/link} despedaçou-se.]=],
		},
		{
			title = "Importância",
			text = [=[A guerra ensinou aos elfos noturnos que a magia arcana quase condenara o mundo. Eles a renunciaram, voltaram-se ao druidismo e ao culto de Elune e começaram sua longa vigília. Ela também deixou {link:illidan-stormrage}Illidan{/link} como traidor aos olhos de seu povo, pois ele trabalhara em segredo com os Bem-nascidos, e depois criou um novo Poço no alto do {link:mount-hyjal}Monte Hyjal{/link}.]=],
		},
	},
})

Translate("ptBR", "great-sundering", {
	title = "Grande Cisão",
	aliases = { "Cisão" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Grande Cisão foi o cataclismo que encerrou a {link:war-of-the-ancients}Guerra dos Antigos{/link}. Quando o {link:well-of-eternity}Poço da Eternidade{/link} desmoronou, o continente único do mundo antigo se despedaçou, e os mares avançaram para encher a ferida. A face de {link:azeroth}Azeroth{/link} mudou para sempre.]=],
		},
		{
			title = "História",
			text = [=[O portal dos Bem-nascidos foi desfeito na hora final da guerra. O Poço, alimentado com mais poder do que podia conter, implodiu. A explosão arrancou o coração do continente. A maior parte do Império Kaldorei, com sua reluzente capital Zin-Azshari, foi engolida pelo mar. A {link:queen-azshara}Rainha Azshara{/link} e muitos de seus Bem-nascidos foram arrastados para baixo das ondas. Onde estivera o Poço, as águas começaram a girar, e nasceu a grande tempestade conhecida como Voragem. Ela nunca cessou.]=],
		},
		{
			title = "O Mundo Depois",
			text = [=[Apenas fragmentos do velho continente permaneceram acima da água. Os maiores deles tornaram-se {link:kalimdor}Kalimdor{/link}, a oeste, e os {link:eastern-kingdoms}Reinos do Leste{/link}, a leste, e a terra gelada de Nortúndria ficou ao norte. Os elfos noturnos sobreviventes reuniram-se nas encostas do {link:mount-hyjal}Monte Hyjal{/link}. Ali descobriram que {link:illidan-stormrage}Illidan Stormrage{/link} havia levado frascos da água do Poço e os derramara num lago da montanha, criando um segundo Poço. Para guardá-lo, os Aspectos plantaram {link:nordrassil}Nordrassil{/link} sobre suas águas.]=],
		},
		{
			title = "Importância",
			text = [=[Para os elfos noturnos, a Cisão foi a prova do custo da {link:arcane-magic}magia arcana{/link}. Para o mundo, significou dez mil anos de separação. Os povos do leste e do oeste esqueceram-se uns dos outros até que a {link:third-war}Terceira Guerra{/link} os reuniu de novo. Diz-se que os {link:naga}nagas{/link} que hoje assombram as costas são os Bem-nascidos afogados, transformados além de qualquer reconhecimento.]=],
		},
	},
})

Translate("ptBR", "troll-wars", {
	title = "Guerras Trolls",
	sections = {
		{
			title = "Resumo",
			text = [=[As Guerras Trolls foram travadas entre os trolls Amani e os jovens reinos dos humanos e dos {link:high-elves}altos elfos{/link}, cerca de dois mil e oitocentos anos antes da abertura do {link:dark-portal}Portal Negro{/link}. Delas nasceram a aliança entre elfos e humanos e os primeiros magos humanos.]=],
		},
		{
			title = "Origens",
			text = [=[Os Bem-nascidos exilados de {link:kalimdor}Kalimdor{/link} fundaram {link:quel-thalas}Quel'Thalas{/link} nas florestas do norte dos {link:eastern-kingdoms}Reinos do Leste{/link}. Aquelas florestas haviam pertencido aos Amani, e os trolls nunca perdoaram o roubo. Guerrearam contra os elfos durante milhares de anos. Por fim, reuniram uma grande hoste, talvez acompanhada de seus parentes Gurubashi, e partiram para destruir Quel'Thalas por completo.]=],
		},
		{
			title = "História",
			text = [=[Na mesma época, {link:thoradin}Thoradin{/link}, da tribo arathi, havia unido as tribos humanas do norte na nação de {link:arathor}Arathor{/link}, com sua capital em {link:stromgarde-keep}Strom{/link}. Os elfos de {link:quel-thalas}Quel'Thalas{/link} enviaram-lhe emissários em desespero. Thoradin concordou em ajudá-los se os elfos ensinassem magia ao seu povo. Os elfos escolheram cem humanos com dom para a arte e lhes ensinaram apenas o necessário. Os exércitos aliados enfrentaram a hoste Amani no sul das {link:alterac-mountains}Montanhas de Alterac{/link}. Os magos humanos e os magísteres élficos fizeram chover fogo sobre os trolls, e as chamas queimaram as feridas que os trolls de outro modo conseguem curar. Os Amani romperam as fileiras e fugiram, e seu império nunca se recuperou.]=],
		},
		{
			title = "Importância",
			text = [=[Em gratidão, os elfos de {link:quel-thalas}Quel'Thalas{/link} juraram amizade à linhagem de {link:thoradin}Thoradin{/link}. Esse juramento os levaria à {link:second-war}Segunda Guerra{/link}. A magia ensinada à humanidade espalhou-se muito além dos primeiros cem. Deu origem a {link:dalaran}Dalaran{/link} e ao {link:kirin-tor}Kirin Tor{/link}, e atraiu mais uma vez a atenção da {link:burning-legion}Legião Ardente{/link}.]=],
		},
	},
})

Translate("ptBR", "first-war", {
	title = "Primeira Guerra",
	sections = {
		{
			title = "Resumo",
			text = [=[A Primeira Guerra foi a invasão do reino humano de {link:azeroth}Azeroth{/link} pela {link:horde}Horda{/link} {link:orcs}orc{/link}. Começou quando o {link:dark-portal}Portal Negro{/link} se abriu no Lamaçal Negro e terminou com a queda de {link:stormwind-city}Ventobravo{/link}. Foi a primeira guerra entre orcs e humanos e o início da era que moldou o mundo desde então.]=],
		},
		{
			title = "Origens",
			text = [=[Em seu mundo, Draenor, os {link:orcs}orcs{/link} haviam sido corrompidos pelo senhor demoníaco {link:kil-jaeden}Kil'jaeden{/link} por meio do bruxo {link:gul-dan}Gul'dan{/link} e de seu {link:shadow-council}Conselho das Sombras{/link}. Sua terra natal estava morrendo. Em {link:azeroth}Azeroth{/link}, {link:medivh}Medivh{/link}, o Guardião de {link:tirisfal-glades}Tirisfal{/link}, estava havia muito possuído pelo espírito de {link:sargeras}Sargeras{/link}. Trabalhando com Gul'dan, Medivh ajudou a abrir um portal entre os dois mundos.]=],
		},
		{
			title = "História",
			text = [=[Os primeiros orcs atravessaram em pequeno número e saquearam o Lamaçal Negro. Então o portal se alargou e a {link:horde}Horda{/link} veio com força, sob o chefe guerreiro Blackhand. O Rei {link:llane-wrynn}Llane Wrynn{/link} e seu campeão {link:anduin-lothar}Anduin Lothar{/link} os combateram durante anos por todo o reino do sul. A Horda queimou as fazendas de {link:elwynn-forest}Elwynn{/link}, as florestas da {link:duskwood}Floresta do Crepúsculo{/link} e a {link:northshire-abbey}Abadia de Vila Norte{/link}. Lothar e o jovem mago {link:khadgar}Khadgar{/link} enfim mataram o Guardião enlouquecido em sua torre de {link:karazhan}Karazhan{/link}. Era tarde demais para o reino. A meia-{link:orcs}orc{/link} {link:garona}Garona{/link} matou o Rei Llane em seu próprio castelo, {link:orgrim-doomhammer}Orgrim Doomhammer{/link} tomou a Horda de Blackhand, e {link:stormwind-city}Ventobravo{/link} foi saqueada.]=],
		},
		{
			title = "Importância",
			text = [=[{link:anduin-lothar}Lothar{/link} levou os sobreviventes para o norte, através do mar, até {link:lordaeron}Lordaeron{/link}, levando consigo {link:varian-wrynn}Varian{/link}, filho de {link:llane-wrynn}Llane{/link}. Seus avisos levaram o Rei {link:terenas-menethil}Terenas Menethil{/link} a reunir a {link:alliance}Aliança{/link} e se preparar para a {link:second-war}Segunda Guerra{/link}.]=],
		},
	},
})

Translate("ptBR", "second-war", {
	title = "Segunda Guerra",
	sections = {
		{
			title = "Resumo",
			text = [=[A Segunda Guerra foi travada entre a {link:horde}Horda{/link} sob {link:orgrim-doomhammer}Orgrim Doomhammer{/link} e a {link:alliance}Aliança{/link} de {link:lordaeron}Lordaeron{/link}. A Horda marchou para o norte para conquistar os reinos humanos que sobreviveram à {link:first-war}Primeira Guerra{/link}. Foi derrotada no Pico da {link:blackrock-mountain}Rocha Negra{/link}.]=],
		},
		{
			title = "História",
			text = [=[O Rei {link:terenas-menethil}Terenas Menethil{/link} de {link:lordaeron}Lordaeron{/link} reuniu os reinos humanos numa {link:alliance}Aliança{/link}, com {link:anduin-lothar}Anduin Lothar{/link} como comandante. Os anões de {link:kingdom-of-ironforge}Altaforja{/link} e os gnomos juntaram-se a eles. Também os elfos de {link:quel-thalas}Quel'Thalas{/link}, presos pelo velho juramento que haviam feito à linhagem de {link:thoradin}Thoradin{/link}, pois Lothar era seu último herdeiro. A {link:horde}Horda{/link} veio com mais força que antes. Doomhammer trouxe ogros e os trolls Amani de Zul'jin para seu lado. O {link:dragonmaw-clan}clã Presa do Dragão{/link} escravizou a revoada dragônica vermelha e cavalgou seus dragões para a batalha. {link:gul-dan}Gul'dan{/link} ergueu cavaleiros da morte dos cadáveres de cavaleiros humanos caídos. A Horda tomou Khaz Modan e queimou as fronteiras de Quel'Thalas. Lorde Perenolde de {link:alterac-mountains}Alterac{/link} traiu a Aliança em favor dos orcs. A Horda chegou às próprias muralhas da capital de Lordaeron.]=],
		},
		{
			title = "A Virada da Guerra",
			text = [=[No auge da guerra, {link:gul-dan}Gul'dan{/link} abandonou Doomhammer. Partiu por mar com seus seguidores em busca da Tumba de {link:sargeras}Sargeras{/link}, e a {link:horde}Horda{/link} foi obrigada a voltar para puni-lo. A {link:alliance}Aliança{/link} aproveitou o momento. Empurrou a Horda para o sul, até o Pico da {link:blackrock-mountain}Rocha Negra{/link}. Ali {link:anduin-lothar}Lothar{/link} tombou pela mão de Doomhammer. Seu tenente, {link:turalyon}Turalyon{/link}, tomou seu estandarte e esmagou a Horda nas {link:burning-steppes}Estepes Ardentes{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Os orcs sobreviventes foram conduzidos a {link:internment-camps}campos de internação{/link}. O {link:dark-portal}Portal Negro{/link} foi destruído. A {link:alliance}Aliança{/link} vencera, mas sua vitória custou caro. Seus reinos logo brigaram pelo custo dos campos, e {link:gilneas}Gilneas{/link} e {link:stromgarde-keep}Stromgarde{/link} deixaram a Aliança.]=],
		},
	},
})

Translate("ptBR", "third-war", {
	title = "Terceira Guerra",
	sections = {
		{
			title = "Resumo",
			text = [=[A Terceira Guerra foi a segunda invasão de {link:azeroth}Azeroth{/link} pela {link:burning-legion}Legião Ardente{/link}. Começou em {link:lordaeron}Lordaeron{/link} com uma praga de morte-vida e terminou em {link:kalimdor}Kalimdor{/link} com a destruição de {link:archimonde}Archimonde{/link}. Custou à humanidade seu maior reino e aos elfos noturnos sua imortalidade.]=],
		},
		{
			title = "Origens",
			text = [=[Depois da {link:second-war}Segunda Guerra{/link}, o demônio {link:kil-jaeden}Kil'jaeden{/link} prendeu o espírito do xamã {link:orcs}orc{/link} {link:ner-zhul}Ner'zhul{/link} numa prisão congelada em Nortúndria e fez dele o Lich Rei. Por meio do necromante {link:kel-thuzad}Kel'Thuzad{/link} e de seu {link:cult-of-the-damned}Culto dos Malditos{/link}, o Lich Rei espalhou uma praga pelas aldeias de {link:lordaeron}Lordaeron{/link}. Suas vítimas ergueram-se como o {link:scourge}Flagelo{/link} morto-vivo. Ao mesmo tempo, o jovem orc {link:thrall}Thrall{/link} libertou seu povo dos {link:internment-camps}campos de internação{/link} e forjou uma nova {link:horde}Horda{/link}.]=],
		},
		{
			title = "História",
			text = [=[Um profeta misterioso advertiu os reis do leste a fugir para o oeste, através do mar. O Rei {link:terenas-menethil}Terenas Menethil{/link} não quis ouvir, mas {link:thrall}Thrall{/link} e {link:jaina-proudmoore}Jaina Proudmoore{/link} atenderam ao chamado. O profeta era {link:medivh}Medivh{/link}, de volta da morte. Em {link:lordaeron}Lordaeron{/link}, o Príncipe {link:arthas-menethil}Arthas Menethil{/link} caçou a praga até sua origem. Depois do {link:culling-of-stratholme}Expurgo de Stratholme{/link}, ele navegou até Nortúndria e empunhou a lâmina amaldiçoada Gélido Lamento. Voltou como cavaleiro da morte e provocou a {link:fall-of-lordaeron}Queda de Lordaeron{/link}. O {link:scourge}Flagelo{/link} ergueu {link:kel-thuzad}Kel'Thuzad{/link} na Nascente do Sol de {link:quel-thalas}Quel'Thalas{/link}, e {link:archimonde}Archimonde{/link} entrou no mundo em {link:dalaran}Dalaran{/link} e a destruiu. Então a Legião seguiu a {link:horde}Horda{/link} e os humanos até {link:kalimdor}Kalimdor{/link}. Ali os elfos noturnos se ergueram de sua vigília.]=],
		},
		{
			title = "Importância",
			text = [=[{link:orcs}Orcs{/link}, humanos e elfos noturnos enfim fizeram causa comum. Na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, destruíram {link:archimonde}Archimonde{/link}. Da guerra vieram as terras da nova {link:horde}Horda{/link} em {link:kalimdor}Kalimdor{/link}, a cidade de {link:theramore-isle}Theramore{/link} e os {link:forsaken}Renegados{/link}. Suas feridas ainda estão abertas.]=],
		},
	},
})

Translate("ptBR", "battle-of-mount-hyjal", {
	title = "Batalha do Monte Hyjal",
	aliases = { "Batalha de Hyjal" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Batalha do Monte Hyjal foi a última batalha da {link:third-war}Terceira Guerra{/link}. Nas encostas da montanha sagrada, orcs, humanos e elfos noturnos lutaram juntos contra a {link:burning-legion}Legião Ardente{/link}. O senhor demoníaco {link:archimonde}Archimonde{/link} foi destruído junto às raízes de {link:nordrassil}Nordrassil{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[A Legião viera a {link:kalimdor}Kalimdor{/link} pela Árvore do Mundo. {link:archimonde}Archimonde{/link} pretendia drenar o poder do segundo {link:well-of-eternity}Poço da Eternidade{/link} que ficava sob suas raízes e, com isso, consumir o mundo. O {link:scourge}Flagelo{/link} marchava à sua frente. Os elfos noturnos de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} e {link:malfurion-stormrage}Malfurion Stormrage{/link} não podiam resistir sozinhos. {link:medivh}Medivh{/link} reuniu seus líderes, {link:thrall}Thrall{/link}, da {link:horde}Horda{/link}, e {link:jaina-proudmoore}Jaina Proudmoore{/link}, dos humanos. Disse-lhes que só juntos poderiam sobreviver.]=],
		},
		{
			title = "História",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} concebeu o plano. Os humanos resistiram nas encostas mais baixas, depois os orcs mais acima, e cada um aguentou o quanto pôde antes de recuar. Enquanto lutavam, Malfurion preparava uma armadilha no cume. {link:archimonde}Archimonde{/link} rompeu cada linha por vez e enfim alcançou a árvore. Enquanto ele escalava {link:nordrassil}Nordrassil{/link}, Malfurion soou a Trombeta de {link:cenarius}Cenarius{/link}. Os espíritos dos ancestrais dos elfos noturnos, reunidos como incontáveis fogos-fátuos, enxamearam sobre o demônio. Seu poder, e o poder da Árvore do Mundo, foi liberado numa única explosão. Archimonde foi destruído.]=],
		},
		{
			title = "Importância",
			text = [=[A vitória salvou o mundo, mas veio a um grande preço. {link:nordrassil}Nordrassil{/link} entregou seu poder, e os elfos noturnos perderam a imortalidade que ela lhes concedia. A árvore foi chamuscada, mas não morta. A batalha também forjou uma breve paz entre a {link:alliance}Aliança{/link} e a {link:horde}Horda{/link}.]=],
		},
	},
})

Translate("ptBR", "culling-of-stratholme", {
	title = "Expurgo de Stratholme",
	sections = {
		{
			title = "Resumo",
			text = [=[O Expurgo de Stratholme foi o massacre do povo de Stratholme pelos soldados do Príncipe {link:arthas-menethil}Arthas Menethil{/link}. Aconteceu na {link:third-war}Terceira Guerra{/link}, quando a praga da morte-vida chegou à cidade. Marcou o início da queda do príncipe.]=],
		},
		{
			title = "Origens",
			text = [=[{link:arthas-menethil}Arthas{/link} havia caçado a praga por {link:lordaeron}Lordaeron{/link} com a feiticeira {link:jaina-proudmoore}Jaina Proudmoore{/link} e seu mentor, {link:uther-the-lightbringer}Uther, o Arauto da Luz{/link}. Descobriu que o {link:cult-of-the-damned}Culto dos Malditos{/link} contaminara os grãos enviados dos celeiros de {link:ruins-of-andorhal}Andorhal{/link}. Em Stratholme, descobriu que os grãos contaminados já haviam sido distribuídos. Todos os que os haviam comido logo morreriam e se ergueriam de novo como parte do {link:scourge}Flagelo{/link}.]=],
		},
		{
			title = "História",
			text = [=[{link:arthas-menethil}Arthas{/link} ordenou que a cidade fosse expurgada antes que seu povo se transformasse. {link:uther-the-lightbringer}Uther{/link} recusou-se a participar, e Arthas o destituiu do comando por traição. {link:jaina-proudmoore}Jaina{/link} não quis assistir e o deixou. O príncipe conduziu os soldados que permaneceram leais para dentro de Stratholme e passou seu povo a fio de espada, casa por casa. Onde eles ainda não haviam chegado, os cidadãos já se transformavam. O senhor do medo Mal'Ganis esperava na cidade. Zombou do príncipe e o desafiou a segui-lo até Nortúndria. Arthas jurou caçá-lo.]=],
		},
		{
			title = "Importância",
			text = [=[O Expurgo rompeu o laço entre {link:arthas-menethil}Arthas{/link} e os que o amavam. Mandou-o para o norte, para Gélido Lamento e para a {link:fall-of-lordaeron}Queda de Lordaeron{/link}.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Stratholme jaz em ruínas nas {link:eastern-plaguelands}Terras Pestilentas Orientais{/link}. O {link:scourge}Flagelo{/link} domina boa parte da cidade. A {link:scarlet-crusade}Cruzada Escarlate{/link} agarra-se ao resto, ainda combatendo os mortos que a espada de {link:arthas-menethil}Arthas{/link} não pôde salvar.]=],
		},
	},
})

Translate("ptBR", "fall-of-lordaeron", {
	title = "Queda de Lordaeron",
	sections = {
		{
			title = "Resumo",
			text = [=[A Queda de Lordaeron foi a ruína do maior reino humano pelo {link:scourge}Flagelo{/link}. Veio na {link:third-war}Terceira Guerra{/link}, quando o Príncipe {link:arthas-menethil}Arthas Menethil{/link} voltou de Nortúndria como servo do Lich Rei. De todos os reinos que haviam liderado a {link:alliance}Aliança{/link}, nenhum caiu tão fundo nem tão depressa.]=],
		},
		{
			title = "História",
			text = [=[Em Nortúndria, {link:arthas-menethil}Arthas{/link} empunhou a lâmina rúnica Gélido Lamento e matou o senhor do medo Mal'Ganis. Perdeu sua alma para a lâmina. Navegou de volta para casa, e o povo da capital o saudou como herói. Ele entrou na sala do trono e matou seu pai, o Rei {link:terenas-menethil}Terenas Menethil{/link}. O {link:scourge}Flagelo{/link} varreu o reino atrás dele. Arthas matou {link:uther-the-lightbringer}Uther, o Arauto da Luz{/link}, e tomou as cinzas da urna de seu pai, para que os restos de {link:kel-thuzad}Kel'Thuzad{/link} pudessem ser levados nela. Marchou sobre {link:quel-thalas}Quel'Thalas{/link}, abateu seus defensores sob {link:sylvanas-windrunner}Sylvanas Windrunner{/link} e ergueu Kel'Thuzad nas águas da Nascente do Sol. Pouco depois, o Flagelo ajudou {link:archimonde}Archimonde{/link} a entrar no mundo em {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Depois da Queda",
			text = [=[Quando {link:archimonde}Archimonde{/link} foi destruído, os senhores do medo buscaram governar eles próprios o reino arruinado. {link:arthas-menethil}Arthas{/link} voltou-se contra eles antes de atender ao chamado de seu mestre no norte. {link:sylvanas-windrunner}Sylvanas{/link}, agora morta-viva, libertou-se da vontade do Lich Rei. Ela e seus {link:forsaken}Renegados{/link} derrubaram os senhores do medo e reivindicaram as ruínas da capital.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[{link:lordaeron}Lordaeron{/link} se foi. Seu coração são as Terras Pestilentas, dominadas pelo {link:scourge}Flagelo{/link}. A {link:scarlet-crusade}Cruzada Escarlate{/link} combate os mortos nas {link:tirisfal-glades}Clareiras de Tirisfal{/link} e além. Sob a sala do trono destruída, os {link:forsaken}Renegados{/link} construíram a {link:undercity}Cidade Baixa{/link}.]=],
		},
	},
})

Translate("ptBR", "dark-portal", {
	title = "Portal Negro",
	sections = {
		{
			title = "Resumo",
			text = [=[O Portal Negro é o grande portal entre {link:azeroth}Azeroth{/link} e a terra natal dos orcs, Draenor. Ele se ergue na {link:blasted-lands}Barreira do Inferno{/link}, que já foram os pântanos do Lamaçal Negro. Por ele veio a {link:horde}Horda{/link}, e com ele começou a {link:first-war}Primeira Guerra{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[O portal foi aberto pelo bruxo {link:gul-dan}Gul'dan{/link} e seu {link:shadow-council}Conselho das Sombras{/link}, a partir de Draenor, com a ajuda de {link:medivh}Medivh{/link} em {link:azeroth}Azeroth{/link}. Medivh era o Guardião de {link:tirisfal-glades}Tirisfal{/link}, mas sua mente estava havia muito dominada por {link:sargeras}Sargeras{/link}, senhor da {link:burning-legion}Legião Ardente{/link}. No início a fenda era estreita, e só alguns batedores passavam. Depois foi alargada, e a {link:horde}Horda{/link} inteira atravessou para o pântano.]=],
		},
		{
			title = "História",
			text = [=[A {link:horde}Horda{/link} construiu uma grande fortaleza ao redor do portal, e ele se tornou sua estrada para reforços. Quando a {link:second-war}Segunda Guerra{/link} foi perdida, a {link:alliance}Aliança{/link} destruiu o Portal Negro. Alguns anos depois, o xamã {link:ner-zhul}Ner'zhul{/link} o abriu de novo e conduziu uma nova Horda através dele para roubar artefatos de poder. A Aliança enviou uma expedição a Draenor para acabar com a ameaça em sua origem. Ner'zhul abriu fendas para outros mundos, e o portal foi destruído novamente. A expedição não voltou. Ninguém em {link:azeroth}Azeroth{/link} sabe o que aconteceu com ela.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[O Portal Negro está escuro e silencioso na extremidade sul da {link:blasted-lands}Barreira do Inferno{/link}. Os magos e soldados da {link:nethergarde-keep}Bastilha de Etergarde{/link} o vigiam. Demônios ainda vagam pela terra estéril ao redor.]=],
		},
	},
})

Translate("ptBR", "well-of-eternity", {
	title = "Poço da Eternidade",
	sections = {
		{
			title = "Resumo",
			text = [=[O Poço da Eternidade era um vasto lago de poder arcano no coração do mundo antigo. Em suas margens ergueu-se o Império Kaldorei. Sua destruição encerrou a {link:war-of-the-ancients}Guerra dos Antigos{/link} e provocou a {link:great-sundering}Grande Cisão{/link}.]=],
		},
		{
			title = "Natureza",
			text = [=[As histórias mais antigas dizem que o Poço preenchia uma ferida na terra, deixada pela guerra dos Titãs contra os Deuses Antigos. Suas águas eram negras e profundas, e continham o poder bruto do próprio mundo. Os trolls que se estabeleceram perto dele foram transformados ao longo de muitas gerações e tornaram-se os {link:night-elves}elfos noturnos{/link}. Aprenderam a manejar seu poder, e seu domínio da {link:arcane-magic}magia arcana{/link} fez de seu império a maravilha do mundo.]=],
		},
		{
			title = "História",
			text = [=[A rainha dos elfos noturnos, {link:queen-azshara}Azshara{/link}, construiu seu palácio nas margens do Poço, e seus Bem-nascidos sorviam dele cada vez mais fundo. Sua magia atraiu a {link:burning-legion}Legião Ardente{/link}. Os Bem-nascidos tentaram abrir um portal para {link:sargeras}Sargeras{/link} dentro do próprio Poço. Quando o portal foi desfeito, o Poço desmoronou, e o continente se despedaçou. Onde ele estivera, hoje ruge o Voragem.]=],
		},
		{
			title = "Seu Legado",
			text = [=[Algo do Poço sobreviveu. {link:illidan-stormrage}Illidan Stormrage{/link} salvou frascos de suas águas e os derramou num lago do {link:mount-hyjal}Monte Hyjal{/link}, criando um segundo Poço. Ali os Aspectos plantaram {link:nordrassil}Nordrassil{/link}. Os Bem-nascidos exilados levaram outro frasco para o leste. Com ele criaram a Nascente do Sol, a fonte de {link:quel-thalas}Quel'Thalas{/link}. Na {link:third-war}Terceira Guerra{/link}, {link:archimonde}Archimonde{/link} veio a {link:kalimdor}Kalimdor{/link} para consumir o poder do segundo Poço, e fracassou.]=],
		},
	},
})

Translate("ptBR", "nordrassil", {
	title = "Nordrassil",
	sections = {
		{
			title = "Resumo",
			text = [=[Nordrassil é a Árvore do Mundo, que se ergue do cume do {link:mount-hyjal}Monte Hyjal{/link}, em {link:kalimdor}Kalimdor{/link}. Por dez mil anos, ela guardou o segundo {link:well-of-eternity}Poço da Eternidade{/link} e deu aos {link:night-elves}elfos noturnos{/link} sua imortalidade. Foi o centro da {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Depois da {link:great-sundering}Grande Cisão{/link}, os elfos noturnos sobreviventes descobriram que {link:illidan-stormrage}Illidan Stormrage{/link} havia criado um novo Poço no alto do {link:mount-hyjal}Monte Hyjal{/link}. Os Aspectos dragônicos vieram até eles. {link:alexstrasza}Alexstrasza{/link} pôs uma semente sagrada nas águas do novo Poço, e dela ergueu-se uma grande árvore, cujas raízes bebiam do Poço e o selavam. Nozdormu abençoou a árvore para que os elfos noturnos vivessem enquanto ela estivesse de pé. Ysera a ligou ao {link:emerald-dream}Sonho Esmeralda{/link}, para que os druidas pudessem andar pelo Sonho através dela.]=],
		},
		{
			title = "História",
			text = [=[Sob seus galhos, os elfos noturnos mantiveram sua longa vigília. Os druidas de {link:malfurion-stormrage}Malfurion Stormrage{/link} dormiam à sua sombra, com os espíritos vagando pelo Sonho. Na {link:third-war}Terceira Guerra{/link}, {link:archimonde}Archimonde{/link} marchou sobre a árvore para drenar o Poço sob ela. Enquanto ele escalava seu tronco, Malfurion chamou os espíritos dos ancestrais, e o poder de Nordrassil foi gasto na destruição do demônio.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Nordrassil ainda está de pé, marcada e enfraquecida. Os elfos noturnos já não são imortais. Plantaram uma nova árvore, {link:teldrassil}Teldrassil{/link}, ao largo da costa norte, mas ela cresceu sem a bênção dos Aspectos. Muitos dos velhos druidas duvidam que ela devesse sequer ter sido plantada.]=],
		},
	},
})

Translate("ptBR", "holy-light", {
	title = "Luz Sagrada",
	sections = {
		{
			title = "Resumo",
			text = [=[A Luz Sagrada é o poder da fé e da virtude que responde aos devotos. Seus sacerdotes curam feridas e restauram espíritos. Seus paladinos a levam à batalha como escudo e como arma contra os mortos-vivos e os demônios. A maioria dos humanos dos {link:eastern-kingdoms}Reinos do Leste{/link} foi criada em sua fé, e muitos {link:dwarves}anões{/link} agora a compartilham.]=],
		},
		{
			title = "Natureza",
			text = [=[Os fiéis não ensinam que a Luz é um deus. Ensinam que ela habita em todos que buscam a virtude, e que se fortalece pela compaixão, pela coragem e pelo sacrifício. Ela não pode ser roubada nem dobrada à crueldade. Os que tentam manejá-la sem fé descobrem que ela não lhes responde.]=],
		},
		{
			title = "História",
			text = [=[A fé da Luz tem raízes profundas entre a humanidade, que remontam aos dias de {link:arathor}Arathor{/link}. No reino de {link:stormwind-city}Ventobravo{/link}, ela era guardada na {link:northshire-abbey}Abadia de Vila Norte{/link} e na {link:cathedral-of-light}Catedral da Luz{/link}. Depois da {link:first-war}Primeira Guerra{/link}, o Arcebispo {link:alonsus-faol}Alonsus Faol{/link} viu que só a fé não salvara o sul. Uniu os clérigos da Luz aos melhores cavaleiros de {link:lordaeron}Lordaeron{/link} e fundou a Ordem do Punho de Prata, os primeiros paladinos. {link:uther-the-lightbringer}Uther, o Arauto da Luz{/link}, foi o primeiro deles. Os paladinos lutaram com honra durante a {link:second-war}Segunda Guerra{/link}. Na {link:third-war}Terceira Guerra{/link}, a ordem foi despedaçada. O Príncipe {link:arthas-menethil}Arthas Menethil{/link} havia sido um deles.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[A Luz ainda é o coração da fé de {link:stormwind-city}Ventobravo{/link}, e seus sacerdotes servem em todas as cidades. Em {link:lordaeron}Lordaeron{/link}, ela se tornou um grito de guerra. A {link:scarlet-crusade}Cruzada Escarlate{/link} queima em nome da Luz todos os que suspeita estarem com a praga. A {link:argent-dawn}Aurora Argêntea{/link} combate os mesmos mortos com mão mais firme.]=],
		},
	},
})

Translate("ptBR", "arcane-magic", {
	title = "Magia Arcana",
	sections = {
		{
			title = "Resumo",
			text = [=[A magia arcana é a magia da mente e dos padrões do mundo. Seus mestres dobram o espaço e o tempo, invocam fogo e gelo e veem o que outros não podem ver. É a mais antiga magia aprendida de {link:azeroth}Azeroth{/link}, e a mais perigosa para os que a amam demais.]=],
		},
		{
			title = "Natureza",
			text = [=[O poder arcano pode ser aprendido por quem tem talento e disciplina, mas não dá nada de graça. Os que o manejam passam a ansiar por ele. Ele também chama os demônios da {link:burning-legion}Legião Ardente{/link}, que têm fome de mundos ricos em magia. Toda grande era de poder arcano em {link:azeroth}Azeroth{/link} atraiu o olhar da Legião.]=],
		},
		{
			title = "História",
			text = [=[Os elfos noturnos foram os primeiros a dominar a magia arcana, no {link:well-of-eternity}Poço da Eternidade{/link}, e seus Bem-nascidos a usaram para provocar a {link:war-of-the-ancients}Guerra dos Antigos{/link}. Depois da {link:great-sundering}Grande Cisão{/link}, os elfos noturnos a proibiram. Os Bem-nascidos que não quiseram abandoná-la foram exilados. Fundaram {link:quel-thalas}Quel'Thalas{/link} no leste e tornaram-se os {link:high-elves}altos elfos{/link}. Nas {link:troll-wars}Guerras Trolls{/link}, ensinaram magia a cem humanos de {link:arathor}Arathor{/link}. A arte espalhou-se pelas terras humanas. Os magos de Arathor ergueram a cidade de {link:dalaran}Dalaran{/link}, e seu conselho governante, o {link:kirin-tor}Kirin Tor{/link}, zelava pelo uso da magia. Quando demônios começaram a surgir em terras humanas, os elfos e os magos fundaram o secreto Conselho de {link:tirisfal-glades}Tirisfal{/link}. Escolheram um Guardião para combater a Legião sozinho. Os últimos Guardiões foram {link:aegwynn}Aegwynn{/link} e seu filho, {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[{link:dalaran}Dalaran{/link} foi destruída por {link:archimonde}Archimonde{/link} na {link:third-war}Terceira Guerra{/link}. Agora seus magos a reconstroem atrás de uma cintilante barreira violeta nos contrafortes de {link:alterac-mountains}Alterac{/link}. Magos ainda se formam em {link:stormwind-city}Ventobravo{/link}, {link:ironforge}Altaforja{/link} e {link:theramore-isle}Theramore{/link}. Entre os elfos noturnos, a velha lei contra a magia arcana continua valendo.]=],
		},
	},
})

Translate("ptBR", "fel-magic", {
	title = "Magia Vil",
	sections = {
		{
			title = "Resumo",
			text = [=[A magia vil é a magia da {link:burning-legion}Legião Ardente{/link}. Ela tira seu poder da destruição e do roubo da vida. Arde com um fogo verde doentio e envenena a terra e as almas dos que a usam. Bruxos ainda negociam com ela, sabendo o preço.]=],
		},
		{
			title = "Natureza",
			text = [=[O poder vil é rápido e forte, e exige pouco estudo. Exige, em vez disso, que algo seja consumido: uma vida, uma alma, a saúde da terra. Os que o usam são lentamente transformados, no corpo e no coração. Os lugares onde ele foi usado com frequência murcham e apodrecem.]=],
		},
		{
			title = "História",
			text = [=[A magia vil chegou a {link:azeroth}Azeroth{/link} pela primeira vez com a Legião, na {link:war-of-the-ancients}Guerra dos Antigos{/link}. Muitos Bem-nascidos que serviam aos demônios foram deformados em {link:satyrs}sátiros{/link}. Dez mil anos depois, ela veio de novo pelos {link:orcs}orcs{/link}. Em Draenor, o senhor demoníaco {link:kil-jaeden}Kil'jaeden{/link} ensinou seus segredos a {link:gul-dan}Gul'dan{/link} e a seus bruxos. Os chefes orcs beberam o sangue do demônio {link:mannoroth}Mannoroth{/link}, e ele os encheu de uma fúria terrível. A terra de Draenor morreu sob sua magia. Os orcs trouxeram a maldição pelo {link:dark-portal}Portal Negro{/link} para a {link:first-war}Primeira Guerra{/link} e a {link:second-war}Segunda Guerra{/link}. Na {link:third-war}Terceira Guerra{/link}, {link:grom-hellscream}Grom Hellscream{/link} matou Mannoroth e libertou seu povo do sangue do demônio ao custo da própria vida. {link:illidan-stormrage}Illidan Stormrage{/link} consumiu o {link:skull-of-gul-dan}Crânio de Gul'dan{/link} e assumiu o poder de um demônio.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[As florestas da {link:felwood}Selva Maleva{/link} ainda carregam a mácula da Legião. Os bruxos da {link:burning-blade}Lâmina Ardente{/link} servem a demônios nas sombras de {link:orgrimmar}Orgrimmar{/link} e de {link:durotar}Durotar{/link}. Os sátiros assombram {link:ashenvale}Vale Gris{/link}. Bruxos da {link:alliance}Aliança{/link} e da {link:horde}Horda{/link} ainda estudam a arte. Insistem que são seus mestres.]=],
		},
	},
})

Translate("ptBR", "emerald-dream", {
	title = "Sonho Esmeralda",
	sections = {
		{
			title = "Resumo",
			text = [=[O Sonho Esmeralda é um vasto reino espiritual que espelha o mundo. Ele mostra {link:azeroth}Azeroth{/link} como poderia ter sido, selvagem e intocado pelas mãos dos mortais. Sua guardiã é Ysera, o Aspecto da revoada dragônica verde. Os druidas dos {link:night-elves}elfos noturnos{/link} andam por ele em espírito enquanto seus corpos dormem.]=],
		},
		{
			title = "Natureza",
			text = [=[As crônicas afirmam que os Titãs moldaram o Sonho como uma imagem viva de seu projeto para o mundo. É o reino do crescimento e dos sonhos. Os dragões verdes guardam seus portões, e os espíritos das terras selvagens habitam nele. O tempo e a distância ali não seguem as regras do mundo desperto.]=],
		},
		{
			title = "História",
			text = [=[O semideus {link:cenarius}Cenarius{/link} ensinou a {link:malfurion-stormrage}Malfurion Stormrage{/link} os caminhos do druidismo, e por eles Malfurion aprendeu a entrar no Sonho. Depois da {link:war-of-the-ancients}Guerra dos Antigos{/link}, Ysera ligou {link:nordrassil}Nordrassil{/link} ao Sonho. Por milhares de anos, os druidas do {link:cenarion-circle}Círculo Cenariano{/link} dormiram em grutas ocultas, com os espíritos vagando pelo Sonho, enquanto as {link:sentinels}Sentinelas{/link} guardavam seus corpos. Foram despertados para lutar na {link:third-war}Terceira Guerra{/link}. Depois da vitória, os druidas voltaram ao seu trabalho.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} entrou mais uma vez no Sonho e não voltou. {link:fandral-staghelm}Fandral Staghelm{/link} lidera os druidas em sua ausência. Algo está errado dentro do Sonho. {link:the-drag}Drag{/link}ões verdes são vistos no mundo desperto, e alguns deles já não são o que eram. Os druidas da {link:moonglade}Clareira da Lua{/link} falam de uma escuridão que se espalha pelo Sonho, a que ninguém ainda sabe dar nome.]=],
		},
	},
})

Translate("ptBR", "elements", {
	title = "Elementos",
	sections = {
		{
			title = "Resumo",
			text = [=[Os elementos são as forças vivas da terra, do fogo, da água e do ar. Em suas formas brutas, são selvagens e destrutivos. Em equilíbrio, sustentam o mundo. Os xamãs dos {link:orcs}orcs{/link}, dos {link:tauren}taurens{/link} e dos {link:trolls}trolls{/link} falam com os espíritos dos elementos e pedem sua ajuda.]=],
		},
		{
			title = "Natureza",
			text = [=[Quatro grandes senhores elementais governam os elementos. Ragnaros é o senhor do fogo. Therazane é a mãe da pedra. {link:al-akir}Al'Akir{/link} é o senhor dos ventos, cujo reino é {link:skywall}Skywall{/link}. Neptulon é o senhor das marés. Seus servos são selvagens e hostis à vida mortal. Os espíritos menores, porém, aceitam ouvir a razão. Um xamã não os comanda. Um xamã pede, e os espíritos escolhem se respondem.]=],
		},
		{
			title = "História",
			text = [=[Na primeira era do mundo, os senhores elementais lutaram pelos Deuses Antigos. Os Titãs os derrotaram e os prenderam num reino separado do mundo. Em Draenor, os orcs eram um povo de xamãs. Quando {link:gul-dan}Gul'dan{/link} os voltou para a magia demoníaca, os espíritos os abandonaram. Muito mais tarde, em Khaz Modan, o thane {link:dark-iron-dwarves}Ferro Negro{/link} {link:ruins-of-thaurissan}Thaurissan{/link} invocou Ragnaros ao mundo. A invocação matou o thane e ergueu a {link:blackrock-mountain}Montanha Rocha Negra{/link}. Ragnaros habita sob ela desde então. Depois da {link:second-war}Segunda Guerra{/link}, o velho xamã {link:drek-thar}Drek'Thar{/link} ensinou os caminhos dos espíritos ao jovem {link:thrall}Thrall{/link}. Os elementos responderam à nova {link:horde}Horda{/link} como não haviam respondido à antiga.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Ragnaros governa os anões {link:dark-iron-dwarves}Ferro Negro{/link} das profundezas derretidas da {link:blackrock-mountain}Montanha Rocha Negra{/link}. O {link:twilight-s-hammer}Martelo do Crepúsculo{/link} busca despertar os elementos para seus próprios fins. Os xamãs da {link:horde}Horda{/link} mantêm o velho equilíbrio, como seus ancestrais faziam antes que os demônios chegassem.]=],
		},
	},
})
